import React from 'react'
import { useParams } from 'react-router-dom';
import { Property } from '../../types/property';
import Header from '../Home/Header';

import PropertyDetails from './PropertyDetails';
import PropertyImages from './PropertyImages';
import PropertyLocalization from './PropertyLocalization';

import {DetailsWrapper,BodyContainer,TitleContainer, ImageContainer, DetailsLocalizationContainer, PropertyItemImageContainer} from './styles';


type Props = {
    property: Property;
}





const PropertyDetail = ()=> {
    const params = useParams();
    
    return(
      <DetailsWrapper>
          <Header />
          <BodyContainer>
            
              <ImageContainer>
                <PropertyImages />
            <PropertyItemImageContainer/>
              </ImageContainer>
             
               
                  <PropertyDetails propertyId={`${params.propertyId}`}/>
                          <DetailsLocalizationContainer>
                              < PropertyLocalization />
                          </DetailsLocalizationContainer>
             
          </BodyContainer>
      </DetailsWrapper>
    )
}


export default PropertyDetail
